	KEY_WHO_CONFIRM = "Поискать их через /who: выбранных Лордов и Капитанов, ещё не замеченных в своей гильдии, - %d (один поиск за щелчок)",
	KEY_WHO_GAMEPAD = "В интерфейсе для геймпада твой /who ищет в каждой выбранной гильдии (одна за щелчок, никогда по имени), а в той же гильдии снова - через минуту после последнего поиска: Лорды и Капитаны, которых он покажет в их гильдии, получают ключ.",
	KING = "Король",
	KING_ARROW_DENIED = "Менять стрелку к Королю могут только Король, действующий Высший совет или уполномоченный модератор Стражи.",
	KING_ARROW_DISABLED = "Стрелка к Королю на миникарте выключена. Его корона и выбор показа не изменились.",
